  const el = document.elementFromPoint(rect.x + rect.width/2, rect.y + rect.height/2);
  return JSON.stringify({
    rect: {x: rect.x, y: rect.y, w: rect.width, h: rect.height},
    topElement: el ? el.outerHTML.slice(0, 300) : null,
    topIsButton: el === btn
  });
